import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_DIGITS = "0123456789"


def _norm_email(raw):
    s = (raw or "").strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = f"{local}@gmail.com"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw):
    s = (raw or "").lower()
    cuts = [i for i in (s.find("x"), s.find("ext"), s.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _norm_zip(raw):
    z = (raw or "").strip()
    if re.fullmatch(r"[0-9]{4,5}-[0-9]{4}", z):
        z = z.split("-", 1)[0]
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    return z if re.fullmatch(r"[0-9]{5}", z) else ""


def _norm_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _norm_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def _best(members, field):
    """Pick the preferred value of `field` among members with a non-empty value:
    manual sources first, then most recent `updated`, then earliest input row."""
    cands = [r for r in members if r[field]]
    if not cands:
        return ""
    best = min(
        cands,
        key=lambda r: (
            r["source"] != "manual",
            -((r["updated"] or datetime.min) - datetime.min),
        ),
    )
    return best[field]


def dedupe_contacts(rows):
    # Normalize every row and drop rows with neither a valid email nor a valid phone.
    recs = []
    for idx, row in enumerate(rows):
        def g(key):
            return row.get(key) or ""

        email = _norm_email(g("email"))
        if not _valid_email(email):
            email = ""
        phone = _norm_phone(g("phone"))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        recs.append({
            "idx": idx,
            "first_name": _norm_name(g("first_name")),
            "last_name": _norm_name(g("last_name")),
            "zip": _norm_zip(g("zip")),
            "email": email,
            "phone": phone,
            "source": g("source").strip().lower(),
            "tags": _norm_tags(g("tags")),
            "opted_out": g("opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(g("updated")),
        })

    # Union-find over record positions, so matching is transitive.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    # Two rows match on the same valid email, or on the same valid phone
    # plus the same non-empty last name (case-insensitive).
    first_seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("email", r["email"]))
        if r["phone"] and r["last_name"]:
            keys.append(("phone", r["phone"], r["last_name"].lower()))
        for key in keys:
            if key in first_seen:
                union(first_seen[key], i)
            else:
                first_seen[key] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)

    # Output people in order of their earliest input row.
    ordered = sorted(groups.values(), key=lambda grp: recs[grp[0]]["idx"])

    result = []
    for grp in ordered:
        members = [recs[i] for i in grp]

        tags = set()
        for r in members:
            tags |= r["tags"]

        updated_vals = [r["updated"] for r in members if r["updated"]]

        result.append({
            "first_name": _best(members, "first_name"),
            "last_name": _best(members, "last_name"),
            "zip": _best(members, "zip"),
            "email": _best(members, "email"),
            "phone": _best(members, "phone"),
            "source": _best(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
            "updated": max(updated_vals).strftime("%Y-%m-%d") if updated_vals else "",
        })

    return result
